                    document.getElementById("preloader").style.display = "none";
                }, 200);
            };

            document.querySelectorAll('.college-list').forEach((targetNode) => {
                const observer = new MutationObserver(function (mutationsList, observer) {
                    setTimeout(() => {
                        $scope.$apply(function () {
                            $scope.Data_Changes();
                        });
                    }, 50);
                });

                observer.observe(targetNode, {
                    childList: true,
                    subtree: true,
                    characterData: true
                });
            });

            $scope.Data_Changes = function () {
                $scope.dgreIds = $scope.Course_Binds.map(item => item.dgre_id);
                $scope.DistIds = $scope.District_Bind.map(item => item.dist_id);
                $scope.CollegeTypetIds = $scope.universities.map(item => item.ebd_value);
